\end{align*}
or
\begin{equation}\label{E:mrecursion}
    \det M_k= \left(d_k-\frac{2 a_k^2}{a_{k-1}}+\frac{a_k^2 d_{k-1}}{a_{k-1}^2} \right) \det M_{k-1}-a_k^2\left(1-\frac{d_{k-1}}{a_{k-1}}\right)^2 \det M_{k-2} .
\end{equation}
Obviously, the recursion base cases are given by
\begin{align*}
